'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=file=>fs.readFileSync(path.join(root,file),'utf8');
const bootstrap=read('docs/scifi-ui/scripts/formatx-core-real3d-v20.js');
const src=read('docs/scifi-ui/scripts/formatx-reference-lock-v30.js');
const css=read('docs/scifi-ui/styles/formatx-reference-lock-v30.css');
assert.match(bootstrap,/reference-lock-v30/,'production bootstrap must select reference lock v30');
assert.match(bootstrap,/formatx-reference-lock-v30\.js\?v=20260810-uploaded-reference-lock-\d+/,'cache-busted renderer URL missing');
assert.match(bootstrap,/formatx-reference-lock-v30\.css\?v=20260810-uploaded-reference-lock-\d+/,'cache-busted style URL missing');
assert.equal((src.match(/getContext\('webgl2'/g)||[]).length,1,'v30 must create exactly one WebGL2 context');
for(const token of ['gl.enable(gl.DEPTH_TEST)','gl.drawElements(gl.TRIANGLES','gl.drawElements(gl.LINES','function crystal(','function torus(','function sphere(','glass-dominant-sparse-veins-r4','adaptive-60-plus-fps','webglcontextlost']) assert.ok(src.includes(token),`missing release contract: ${token}`);
assert.match(src,/p=\.68/,'reference p-norm exponent missing');
assert.match(src,/mobile\?1\.50:1/,'mobile reference vertical calibration missing');
assert.match(src,/t=\.018/,'thin torus calibration missing');
assert.match(src,/for\(const k of\[2,4,6,8,10,R\]\)/,'sparse transverse veins missing');
assert.match(src,/Math\.floor\(A\/12\)/,'sparse longitudinal veins missing');
assert.match(src,/mesh\(shell,mul\(B,sc\(\.998,\.998,\.998\)\),1,\.30/,'cyan glass surface pass missing');
assert.match(src,/mesh\(shell,mul\(B,sc\(\.992,\.992,\.992\)\),1,\.105/,'violet glass surface pass missing');
assert.ok(src.includes('ready-v30'),'runtime reference ready marker missing');
assert.match(src,/fxCoreImageBacked='false'/,'non-image-backed marker missing');
assert.doesNotMatch(src,/new\s+Image\s*\(|drawImage\s*\(|createImageBitmap\s*\(|backgroundImage/i,'MAG must not use raster imagery to fake 3D');
assert.doesNotMatch(src,/THREE\b|three\.js|babylon|playcanvas|model-viewer/i,'third-party scene engines are forbidden');
assert.match(css,/pointer-events:none/,'GPU stage must not intercept interaction');
assert.match(css,/100dvh/,'dynamic viewport sizing missing');
assert.match(css,/--fx-core-x:50%/,'portrait reference centering missing');
assert.match(css,/40\.2%/,'reference core/horizon vertical alignment missing');
assert.match(css,/top:47\.5%/,'reference floor start missing');
assert.match(css,/perspective\(560px\) rotateX\(63deg\)/,'reference perspective floor missing');
assert.match(css,/saturate\(1\.25\) contrast\(1\.16\) brightness\(2\.60\)/,'reference luminance grade missing');
console.log('PASS: production MAG is a single-context indexed WebGL2 glass-dominant four-sail crystal with calibrated reference luminance, horizon and floor.');
